use vstd::prelude::*;

verus! {

fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        1 <= k,
        k < list.len(),
    ensures
        new_list.len() == list.len() - 1,

        forall|i: int|
            0 <= i && i < (k as int) - 1 ==> new_list[i] == list[i],

        forall|i: int|
            (k as int) - 1 <= i && i < (list.len() as int) - 1 ==> new_list[i] == list[i + 1],

        forall|i: int|
            0 <= i && i < new_list.len() as int ==>
                (i < (k as int) - 1 ==> new_list[i] == list[i]) &&
                (i >= (k as int) - 1 ==> new_list[i] == list[i + 1]),
{
    let mut out: Vec<i32> = Vec::new();
    let remove_idx: usize = k - 1;

    let mut i: usize = 0;
    while i < list.len()
        invariant
            0 <= i as int && i as int <= list.len() as int,
            out.len() == if i <= remove_idx { i } else { i - 1 },
            forall|j: int|
                0 <= j && j < out.len() as int ==>
                    (j < remove_idx as int ==> out[j] == list[j]) &&
                    (j >= remove_idx as int ==> out[j] == list[j + 1]),
    {
        if i != remove_idx {
            out.push(list[i]);
        }
        i += 1;
    }

    out
}

} // verus!